operation Hessenberg_Matrix (qs : Qubit[]) : Unit {
    let n = Length(qs);
    for i in 2^n - 2 .. -1 .. 0{
        RotateToEnd(i, qs);
        (Controlled H)(Most(qs), Tail(qs));
        (Adjoint RotateToEnd)(i, qs);
    }
}

